function c(){if(window.matchMedia("(prefers-reduced-motion: reduce)").matches){document.querySelectorAll(".reveal").forEach(e=>e.classList.add("reveal--in"));return}const t=new IntersectionObserver(e=>{e.forEach(r=>{r.isIntersecting&&(r.target.classList.add("reveal--in"),t.unobserve(r.target))})},{rootMargin:"0px 0px -10% 0px",threshold:.12});document.querySelectorAll(".reveal").forEach(e=>t.observe(e))}export{c as observeReveal};
